import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource@12983fa53d4da19dc1f2a5e6b8c37a0eb12f2aa5/dist/util/mvu_zod.js';

// 正式存档结构与 MVU 叙事投影。规范：docs/协议与状态.md 第 3 节及 D-71。
// 运行时使用酒馆助手注入的全局 z（zod 4.4.3）；测试时由测试文件注入同版本 zod。

const count = (fallback        , min = 0) =>
  z.coerce
    .number()
    .transform(v => Math.max(min, Math.trunc(Number.isFinite(v) ? v : fallback)))
    .prefault(fallback);

const Recovery=z.object({hpPercent:z.number().int().min(0).max(100),sp:z.number().int().min(0).max(100)});
// 装备参数冻结在程序开战记录；弹药仅由本场引擎持有，不增加MVU叙事字段。
const GunOpening=z.object({id:z.string().min(1),power:z.number().positive(),accuracy:z.number().min(0).max(1),capacity:z.number().int().min(1).max(99)});
const BattleGauge = z.object({ hp:z.number().int().min(0), hpMax:z.number().int().positive(), sp:z.number().int().min(0), spMax:z.number().int().positive() })
  .refine(j => j.hp <= j.hpMax && j.sp <= j.spMax, '战斗资源超过上限');
const AllyOpening = BattleGauge.safeExtend({
  id:z.string().min(1), name:z.string().min(1), persona:z.string().min(1), level:z.number().int().positive(),
  stats:z.object({力:z.number().int().positive(),魔:z.number().int().positive(),耐:z.number().int().positive(),速:z.number().int().positive(),运:z.number().int().positive()}),
  skills:z.array(z.string()).max(8),
  equipmentSkills:z.array(z.string().min(1)).max(1).optional(),
  affinities:z.partialRecord(z.enum(['物理','枪击','火炎','冰结','电击','疾风','念动','核热','祝福','咒怨','万能']),z.enum(['普通','弱点','耐性','无效','吸收','反射'])),
  melee:z.object({power:z.number().positive(),accuracy:z.number().min(0).max(1)}),
  gun:GunOpening.optional(),
  recovery:Recovery.optional(),
});
// 原生ID允许进入冻结快照；实际开战/结算仍由catalog核验支持效果，schema保持自包含。
const BattleItems=z.record(z.union([z.enum(['coffee','recov50','recov100','nohar','revive','devil_fruit','life_stone','thaw_stone','hot_stone','antistatic_rock','takemedic_all','takemedic_all_v','kajaclear','kundaclear','takemedic','takemedic_all_z','life_ointment','vanish_ball','spotlight','molotov','freeze_spray','stun_gun','air_cannon']),z.string().regex(/^native_\d+$/)]),z.number().int().min(1).max(99));
const ExpMultiplier=z.union([z.literal(1),z.literal(2)]);
// 仅这些可重复遭遇可以跳过演绎；教学、独立守卫及以后接入的剧情战默认保留叙事。
export function optionalBattleNarration(encounterId        )          {
  return encounterId === 'castle_patrol' || encounterId.startsWith('castle_royal_v1:');
}
// 快照必须完整；不从缺失数据反推或补满开战资源。
const Opening = z.looseObject({
  hp: z.number().int().min(0), hpMax: z.number().int().positive(),
  sp: z.number().int().min(0), spMax: z.number().int().positive(),
  persona: z.string().min(1), level: z.number().int().positive().optional(),
  stats: z.object({ 力: z.number().int().positive(), 魔: z.number().int().positive(), 耐: z.number().int().positive(), 速: z.number().int().positive(), 运: z.number().int().positive() }).optional(),
  skills: z.array(z.string()).max(8).optional(),
  equipmentSkills:z.array(z.string().min(1)).max(1).optional(),
  affinities: z.partialRecord(z.enum(['物理', '枪击', '火炎', '冰结', '电击', '疾风', '念动', '核热', '祝福', '咒怨', '万能']), z.enum(['普通', '弱点', '耐性', '无效', '吸收', '反射'])).optional(),
  melee: z.object({ power: z.number().positive(), accuracy: z.number().min(0).max(1) }).optional(),
  gun:GunOpening.optional(),
  party:z.array(AllyOpening).max(3).refine(a => new Set(a.map(p => p.id)).size === a.length && a.every(p => p.id !== 'joker'), '出战伙伴重复或混入Joker').optional(),
  items:BattleItems.optional(),
  stock:z.array(z.string().min(1)).optional(),capacity:z.number().int().min(1).max(12).optional(),
  surrounded:z.boolean().optional(),
  ailmentWeather:z.boolean().optional(), // 开战时冻结；旧快照未知时不补天气加成。
  expMultiplier:ExpMultiplier.optional(),
  recovery:Recovery.optional(),rules:z.literal('d53').optional(),coop:z.object({fool:z.number().int().min(0).max(10),chariot:z.number().int().min(0).max(10),lovers:z.number().int().min(0).max(10)}).optional(),
}).refine(j => j.hp <= j.hpMax && j.sp <= j.spMax, '开战资源超过上限');
const Result = z.looseObject({
  rules:z.literal('d53').optional(),
  expMultiplier:ExpMultiplier.optional(),
  encounterId: z.literal('castle_awakening'), outcome: z.enum(['won', 'lost','escaped']),
  negotiated:z.object({kind:z.enum(['money','item']),target:z.string().min(1)}).optional(),
  rounds: z.number().int().min(1), exp: z.number().int().min(0), highlights: z.array(z.string()),
  party:z.array(BattleGauge.safeExtend({id:z.string().min(1)})).max(3).optional(),
  itemsUsed:BattleItems.optional(),
  joker: z.looseObject({ hp: z.number().int().min(0), hpMax: z.number().int().positive(), sp: z.number().int().min(0), spMax: z.number().int().positive() })
    .refine(j => j.hp <= j.hpMax && j.sp <= j.spMax, '结算资源超过上限'),
});
const Exploration = z.looseObject({
  路线: z.literal('castle_intro'), 操作ID: z.string().min(1),
  节点: z.enum(['cell', 'corridor']),
  阶段: z.enum(['待觉醒', '觉醒叙述', '战斗中', '战果叙述', '可探索', '逃离叙述', '已结束']),
  待叙述: z.string().min(1).nullable(),
  待叙述源: z.object({ 楼层: z.number().int().min(0), 回复: z.number().int().min(0) }).nullable().prefault(null),
  战斗: z.looseObject({ 遭遇: z.literal('castle_awakening'), 种子: z.number().int().min(0).max(0xffffffff), 开战: Opening, 结果: Result.nullable() }).nullable(),
}).superRefine((e, ctx) => {
  if (['战斗中', '战果叙述'].includes(e.阶段) && !e.战斗) ctx.addIssue({ code: 'custom', message: '缺少本场开战快照', path: ['战斗'] });
  if (e.阶段 === '战斗中' && e.战斗?.结果) ctx.addIssue({ code: 'custom', message: '战斗中不应已有结算', path: ['战斗', '结果'] });
  if (e.阶段 === '战果叙述' && e.战斗?.结果?.outcome !== 'won') ctx.addIssue({ code: 'custom', message: '缺少已提交胜利结果', path: ['战斗', '结果'] });
  if (e.阶段.endsWith('叙述') && !e.待叙述) ctx.addIssue({ code: 'custom', message: '缺少待完成的原请求', path: ['待叙述'] });
  if (e.阶段.endsWith('叙述') && !e.待叙述源) ctx.addIssue({ code: 'custom', message: '缺少原请求所属楼层', path: ['待叙述源'] });
});

// 与组卡内嵌脚本共用：此文件必须自包含，不能运行时 import 菜单数据表。
const Nat = z.number().int().min(0).max(Number.MAX_SAFE_INTEGER);
const Gauge = z.object({ now: Nat, max: z.number().int().positive() }).refine(v => v.now <= v.max);
const AbilityStats = z.object({ 力: Nat, 魔: Nat, 耐: Nat, 速: Nat, 运: Nat });
const PersonaDetail = z.object({ 原型: z.string().min(1).nullable(), 等级: z.number().int().positive().nullable(),
  经验: Nat.nullable(), 能力: AbilityStats.nullable(), 技能: z.array(z.string().min(1)).max(8).nullable(), 待习得:z.array(z.string().min(1)).optional() });
const Place = z.object({ 世界: z.enum(['现实', '认知世界']), 区域: z.string(), 场所: z.string() });
const ActivityDate = z.string().regex(/^\d{4}-\d{2}-\d{2}$/);
const JobProgress = z.object({ 已报名:z.boolean(), 班数:Nat });
// 本批新增进度经驾驶员批准从首次成功操作起计数；缺失时仅只读默认，不在加载时迁移。
const QuickActivities = z.object({ 始记日:ActivityDate, 阁楼整理日:ActivityDate.nullable(), 最近施肥日:ActivityDate.nullable(),
  青汁杯数:Nat, 最近青汁日:ActivityDate.nullable(),
  工作:z.object({ convenience:JobProgress, flower:JobProgress, beef:JobProgress }),
  汉堡通过阶数:Nat.max(3), 观影:z.record(z.string().min(1),Nat.max(2)) });
// 与固定v1敌人键一致；编队1—4只，Berith只允许单独一只。旧两个遭遇ID保持可读。
const CastleNormal = '(?:jack_o_lantern|pixie|mandrake|agathion|bicorn|incubus|cait_sith|kelpie|silky|succubus|angel|archangel)';
const PalaceEncounter = z.union([z.enum(['castle_patrol','kamoshida_boss','castle_will_seed_v1']),z.string().regex(new RegExp(`^castle_royal_v1:(?:berith|${CastleNormal}(?:,${CastleNormal}){0,3})$`))]);
const Gameplay = z.looseObject({
  版本: z.literal(1), 金钱: Nat.nullable(),
  物品: z.record(z.string(), Nat),
  // 只保存下一次叙述需要的最近8笔菜单操作；旧记录缺失不迁移，不代替库存。
  待叙述物品: z.object({ 源: z.object({ 楼层: Nat, 回复: Nat }), 最近操作: z.array(z.string().min(1)).max(8) }).optional(),
  // 本批首批限量商品的已购数；缺失按尚未购买只读计算，不在加载时写回或重置。
  限量购买: z.record(z.string(), Nat).optional(),
  // 槽缺失=旧记录未知；null=已确认空槽。换近战不把另外三槽猜成空。
  装备: z.record(z.string(), z.object({ 近战: z.string().nullable().optional(), 枪械: z.string().nullable().optional(), 防具: z.string().nullable().optional(), 饰品: z.string().nullable().optional() })),
  队友: z.record(z.string(), z.object({ 姓名: z.string(), 代号: z.string(), 等级: z.number().int().positive(), 经验: Nat.nullable(), HP: Gauge, SP: Gauge, 面具: z.string(), 技能: z.array(z.string()), 能力: AbilityStats, 待习得:z.array(z.string().min(1)).optional() })),
  出战: z.array(z.string()).max(4),
  面具详情: z.record(z.string(), PersonaDetail), 全书: z.record(z.string(), PersonaDetail),
  COOP: z.record(z.string(), z.object({ 等级: Nat.max(10), 点数: z.number().min(0).max(Number.MAX_SAFE_INTEGER).multipleOf(0.5).nullable(), 已发生: z.array(z.string()), 最近会面: z.string().nullable(), 建立日:ActivityDate.optional() })),
  五维: z.object({ 知识: Nat.nullable(), 勇气: Nat.nullable(), 灵巧: Nat.nullable(), 温柔: Nat.nullable(), 魅力: Nat.nullable() }),
  日常: z.object({ 训练次数: Nat.nullable(), 咖啡次数: Nat.nullable(), 便捷活动:QuickActivities.optional(),
    生活:z.object({借阅:z.string().nullable(),已买书:z.array(z.string()),阅读:z.record(z.string(),Nat.max(2)),阁楼书:z.boolean(),制作次数:Nat,
      周购:z.record(z.string(),z.object({周:ActivityDate,数量:Nat}))}).optional(),
    记录: z.array(z.object({ id: z.string(), 日期: z.string(), 时段: z.string(), 行动: z.string(), 变化: z.string() })) }).prefault({ 训练次数: null, 咖啡次数: null, 记录: [] }),
  场景: z.object({ 类型: z.enum(['日常', '宫殿', '天鹅绒']), 返回: Place.nullable() }),
  // D-63：只在新开始普通约会时写入；缺失不迁移，null表示已结束。正式结算仍由Game唯一提交。
  约会: z.object({ id:z.string().min(1), 对象:z.enum(['hierophant','lovers','chariot','death']),
    日期:ActivityDate, 时段:z.enum(['白天','放学后','夜晚']), 地点:Place,
    源:z.object({楼层:Nat,回复:Nat}), Rank:Nat.min(1).max(10), 基础点:Nat,
    同属面具:z.boolean(), 礼物:z.string().min(1).nullable() }).nullable().optional(),
  // D-64：新开始COOP逐题快照；已选答案与已确认的叙述序号分开，模型不能推进题号。
  COOP事件:z.object({id:z.string().min(1),对象:z.enum(['hierophant','lovers','chariot','death']),
    原Rank:Nat.max(9),目标Rank:Nat.min(1).max(10),标题:z.string().min(1),日期:ActivityDate,
    时段:z.enum(['白天','放学后','夜晚']),地点:Place,源:z.object({楼层:Nat,回复:Nat}),同属面具:z.boolean(),
    问题:z.array(z.object({prompt:z.string().min(1),options:z.array(z.tuple([z.string().min(1),Nat])).min(1),
      native:z.object({eventId:z.string().min(1),selectionId:z.string().min(1),messageHash:z.string().regex(/^[a-f0-9]{64}$/),responseIds:z.array(z.string().min(1).nullable()).min(1)}).optional()
    }).refine(q=>!q.native||q.native.responseIds.length===q.options.length,'原题回应数量与选项不一致')),
    答案:z.array(z.object({选项:Nat,附言:z.string().max(1000)})),已演绎:Nat.nullable(),
    五维加点:z.object({name:z.enum(['知识','勇气','灵巧','温柔','魅力']),points:Nat}).nullable(),
  }).refine(c=>c.目标Rank===c.原Rank+1&&c.答案.length<=c.问题.length&&c.答案.every((a,i)=>!!c.问题[i].options[a.选项]),'COOP阶段或答案无效')
    .refine(c=>c.已演绎===null?c.答案.length===0:c.已演绎===c.答案.length||c.已演绎===c.答案.length-1,'COOP叙述序号无效').nullable().optional(),
  宫殿: z.object({ 潜入ID: z.string().nullable(), 节点: z.string(), 发现: z.array(z.string()),
    已处理: z.array(z.string()), 路线确保: z.boolean(), 发信日: z.string().nullable(), 夺宝日: z.string().nullable(), 通关: z.boolean(),
    警戒:Nat.max(100).optional(),烟幕:z.boolean().optional(),已开箱:z.array(z.string()).optional(),
    战斗:z.object({ id:z.string().min(1), 遭遇:PalaceEncounter, 种子:z.number().int().min(0).max(0xffffffff), 开战:Opening,
      结果:Result.extend({encounterId:PalaceEncounter}).nullable(),
      战后选择:z.object({摘要:z.string().min(1),请求:z.string().min(1)}).optional() })
      .refine(b=>!b.结果 || b.结果.encounterId === b.遭遇,'结果不属于本场遭遇')
      .refine(b=>!b.战后选择 || (!!b.结果 && b.结果.outcome !== 'lost' && optionalBattleNarration(b.遭遇)),'只有已结算的普通战斗可以选择演绎')
      .nullable().prefault(null) }),
  手机: z.array(z.object({ id: z.string(), 发件人: z.string(), 正文: z.string(), 日期: z.string(),
    回复: z.array(z.object({ id: z.string(), 文本: z.string(), 活动: z.string().nullable() })), 已回复: z.string().nullable() })),
  待操作: z.object({ id: z.string(), 类型: z.enum(['活动', '手机', '潜入', '撤退', '发信']), 请求: z.string().min(1),
    源: z.object({ 楼层: Nat, 回复: Nat }), 日期: z.string(), 行动: z.string() }).nullable(),
});

export const Schema = z.looseObject({
  状态版本: z.literal(1).prefault(1),
  状态修订: z.number().int().min(0).prefault(0),
  探索: Exploration.nullable().prefault(null),
  玩法: Gameplay.nullable().prefault(null),
  日程: z
    .looseObject({
      日期: z.string().regex(/^\d{4}-\d{2}-\d{2}$/).prefault('2016-04-09'),
      时间段: z.enum(['清晨', '上午', '午休', '下午', '放学后', '白天', '夜晚']).prefault('白天'),
    })
    .prefault({}),
  地点: z
    .looseObject({
      世界: z.enum(['现实', '认知世界']).prefault('现实'),
      区域: z.string().prefault('四轩茶屋'),
      场所: z.string().prefault('卢布朗'),
    })
    .prefault({}),
  剧情: z
    .looseObject({
      章节: z.enum(['序章', '鸭志田宫殿']).prefault('序章'),
      已完成事件: z.array(z.string()).prefault([]),
    })
    .prefault({}),
  Joker: z
    .looseObject({
      等级: count(1, 1),
      经验: count(0),
      HP: count(100),
      HP上限: count(100, 1),
      SP: count(50),
      SP上限: count(50, 1),
      Persona: z.array(z.string()).prefault([]),
      当前Persona: z.string().prefault(''),
    })
    .transform(j => ({ ...j, HP: Math.min(j.HP, j.HP上限), SP: Math.min(j.SP, j.SP上限) }            ))
    .prefault({}),
});

                                                       

// MVU 只供叙事读取；战斗重放／去重信息仍由上面的完整 Schema 校验和保存。
const BattleSummary = z.object({
  遭遇: z.string().min(1),
  结果: Result.pick({ outcome: true, rounds: true, exp: true, highlights: true, negotiated: true }).strip().nullable(),
});
const InventoryNotice = '完整库存由程序保管，未列出不等于没有；仅按已确认操作演绎，不自行认定持有、使用或赠送成功。';
export const MvuSchema = Schema.extend({
  探索: z.object({
    路线: Exploration.shape.路线, 节点: Exploration.shape.节点, 阶段: Exploration.shape.阶段,
    战斗: BattleSummary.nullable(),
  }).nullable().prefault(null),
  玩法: Gameplay.omit({ 全书: true, 物品: true, 待叙述物品: true }).strip().extend({
    // optional 仅用于读取旧版完整 MVU；正式同步总是从全书计算，不采信副本计数。
    全书摘要: z.object({ 已登记种类: Nat }).optional(),
    背包说明: z.literal(InventoryNotice).prefault(InventoryNotice),
    最近物品操作: z.array(z.string().min(1)).max(8).optional(),
    宫殿: Gameplay.shape.宫殿.extend({ 战斗: BattleSummary.nullable().prefault(null) }),
    待操作: Gameplay.shape.待操作.unwrap().pick({ 类型: true, 日期: true, 行动: true }).nullable(),
  }).nullable().prefault(null),
});

/** 从已校验的正式状态生成只读副本；不得用该副本反向恢复正式进度。 */
export function stateForMvu(state                         ) {
  const gameplay = state.玩法                  ;
  return MvuSchema.parse({ ...state, ...(gameplay ? {
    玩法: { ...gameplay, 全书摘要: { 已登记种类: Object.keys(gameplay.全书).length }, 最近物品操作: gameplay.待叙述物品?.最近操作,
      宫殿:{...gameplay.宫殿,战斗:gameplay.宫殿.战斗 && optionalBattleNarration(gameplay.宫殿.战斗.遭遇) ? null : gameplay.宫殿.战斗},
      // 战斗收益流水仍在正式存档；下一次闲聊不补发跳过的战报。非战斗日常记录照常供世界书读取。
      日常:{...gameplay.日常,记录:gameplay.日常.记录.filter(r=>!['战斗撤离','交涉索取','交涉获得面具','击败鸭志田','击败宫殿暗影'].includes(r.行动))},
    },
  } : {}) });
}

/** 只有前端可以写的顶层字段。 */
export const FRONTEND_OWNED = ['日程', '地点', '剧情', 'Joker', '状态版本', '状态修订', '探索', '玩法']         ;

$(() => {
  registerMvuSchema(MvuSchema);
});

// 心之怪盗团 · 入口（D-14 远程加载）：主程序和图片不在卡里，按顺序尝试下面的来源。
(async () => {
  const sources = [`https://cdn.jsdelivr.net/gh/cy4268/p5r-phantom-thieves-release@0.3.4/p5r.js`, `https://testingcf.jsdelivr.net/gh/cy4268/p5r-phantom-thieves-release@0.3.4/p5r.js`];
  for (const url of sources) {
    try {
      await import(url);
      return;
    } catch (error) {
      console.warn('[P5R] 来源加载失败：', url, error);
    }
  }
  toastr.error('心之怪盗团的主程序加载失败：所有来源都连不上。请检查网络后刷新页面。', '', { timeOut: 0 });
})();

